  test("crew lead total scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "terms-C", "3");
    await ui.setSetting(pg_uma, "cap", "5.00");
    await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
    expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "20.00", "note": "tpl"})).toBe(true);
    await ui.setSetting(pg_uma, "escalate-after", "7");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "3"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "3"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "terms": "20", "contact": "ben@x"}));
    expect(await ui.bulkRetire(pg_uma, [p_cam, p_ben], "2026-02-25")).toBe(2);
    await ui.showRetired(pg_uma, true);
    expect(await ui.importRates(pg_uma, "A,33.33\nA,7.50,2026-03-05")).toBe(2);
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    expect(await ui.periodAction(pg_uma, "P2", "close")).toBe(true);
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    expect(await ui.exportCsv(pg_uma)).toBe("name,grade,retired-from,due-total\nAda,A,,0.00\nBen,B,2026-02-25,0.00\nCam,C,2026-02-25,0.00\n");
    await ui.refresh(pg_uma);
    expect(await ui.pasteClaims(pg_uma, "Cam,1.00,2026-02-25,")).toBeNull();
    expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B", "gradeFrom": "2026-03-05"})).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "7.77", "date": "2026-02-10", "note": "n", "tags": "a"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "delete")).toBe(true);
    const c_ada_1 = ui.must(await ui.claimFromTemplate(pg_uma, p_ada, "T1"));
    expect(await ui.claimFromTemplate(pg_uma, p_cam, "T1")).toBeNull();
    expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
    await ui.refresh(pg_uma);
